def transform(grid):
    colors = sorted({v for row in grid for v in row})
    if len(colors) == 2:
        mapping = {colors[0]: 0, colors[1]: 2}
    else:
        mapping = {v: v for v in colors}
    return [[mapping[v] for v in row] for row in grid]

